refentry.refsect1:
&reftitle.description;
arrayarray_column arrayarray intstringnullcolumn_key intstringnullindex_key&null;
array_column ले column_key द्वारा पहिचान गरिएको array को एउटा single column from values return गर्दछ। वैकल्पिक रूपमा, return गरिएको array मा रहेका values लाई input array को index_key column from values अनुसार index गर्न एउटा index_key प्रदान गर्न सकिन्छ। array लाई row हरूको एउटा list को रूपमा व्यवहार गरिन्छ, जसमध्ये each आफैँमा एउटा array वा एउटा object हो; प्रत्येक row मा column_key ले नाम दिएको entry वा property नै column हो। न त array न त object भएका row हरू, र त्यो entry वा property अनुपस्थित रहेका row हरूलाई कुनै diagnostic बिना नै skip गरिन्छ। array का keys कहिल्यै पनि preserve गरिँदैनन्।

&reftitle.changelog;







     &Version;
     &Description;





     8.0.0
     index_key parameter द्वारा सूचित गरिएका column हरूमा रहेका Objects लाई अब उप्रान्त string मा cast गरिने छैन र यसको सट्टा अब एउटा TypeError throw हुनेछ।



     7.1.0
     अब Property visibility को पालना गरिन्छ। पहिले, protected र private properties सिधै read गरिन्थे।



     7.0.0
     array का row हरू अब objects का साथै arrays पनि हुन सक्छन्।

  &reftitle.examples;



    एउटा recordset from first name हरूको column प्राप्त गर्ने


<?php

// Array representing a possible record set returned from a database
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$first_names = array_column($records, 'first_name');
print_r($first_names);

?>


    &example.outputs;


Array
(
    [0] => John
    [1] => Sally
    [2] => Jane
    [3] => Peter
)







    "id" column द्वारा index गरिएको, एउटा recordset from last name हरूको column प्राप्त गर्ने


<?php

// Using the $records array from Example #1
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$last_names = array_column($records, 'last_name', 'id');
print_r($last_names);

?>


    &example.outputs;


Array
(
    [2135] => Doe
    [3245] => Smith
    [5342] => Jones
    [5623] => Doe
)







    एउटा object को public "username" property from username हरूको column प्राप्त गर्ने


<?php

class User
{
    public $username;

    public function __construct(string $username)
    {
        $this->username = $username;
    }
}

$users = [
    new User('user 1'),
    new User('user 2'),
    new User('user 3'),
];

print_r(array_column($users, 'username'));

?>


    &example.outputs;


Array
(
    [0] => user 1
    [1] => user 2
    [2] => user 3
)







    magic methods __isset() र __get() प्रयोग गरेर एउटा object को private "name" property from name हरूको column प्राप्त गर्ने


<?php

class Person
{
    private $name;

    public function __construct(string $name)
    {
        $this->name = $name;
    }

    public function __get($prop)
    {
        return $this->$prop;
    }

    public function __isset($prop) : bool
    {
        return isset($this->$prop);
    }
}

$people = [
    new Person('Fred'),
    new Person('Jane'),
    new Person('John'),
];

print_r(array_column($people, 'name'));
?>


    &example.outputs;


Array
(
    [0] => Fred
    [1] => Jane
    [2] => John
)


   यदि __isset() प्रदान गरिएको छैन भने, object ले return गरिएको array मा कुनै पनि entry थप्दैन।
